# Markdown table fragments appended by the narrative writer.
def table(rows,levelcol):
 out=['|Species|'+levelcol+'|Item|Ability|Nature|Points HP/Atk/Def/SpA/SpD/Spe|Moves|','|---|---:|---|---|---|---|---|']
 for p in rows:out.append('|'+ '|'.join([p['species'],str(p.get('level',p.get('level_offset',-1))),p['item'],p['ability'],p['nature'],p['points'],', '.join(p['moves'])])+'|')
 return '\n'.join(out)
